  constructor() { this.events = {}; }

  on(event, fn) {
    if (!this.events[event]) return () => {};

    const listeners = (this.events[event] || []).slice();

    // Add listener to the end of current list for registration order consistency.
    let index;
     try{
        var arr=this.getListenersArrayInternal(this,event);
         this.setListenerAtIndex(arr,fn,arr.length-1); 
      }catch(e){
          console.log("Error adding on",e)
       }

    return () => {
            const listeners = (this.events[event] || []).slice();
             for(let i=0;i<listeners.length; ++i) if(listeners[i].originalFn === fn.originalFn && (!fn.id||!listners.find(l=>l===f))) { // simplified check
                 this.removeListener(event, index);
            }
        };
