export const curry = <T extends unknown[], R>(fn: (...args: T) => R): ((...partialArgs: Partial<T>) => any) & (() => void | never) =>
  (firstArg?: ...restOfFirstCallParameters of Parameters<typeof fn>): ReturnType<(...params: [...Partial<[...]>, ...(RestType>))>> {
    const arity = getArity(fn);

    if (!isUndefined(firstArg as unknown, restArgs.length === arguments.length -1 ? undefined : firstArg) && 
        (restOfFirstCallParameters?.length ?? 0 < parametersLength || isFunction(restParams))) return fn(...(firstArgumentArray));

      const remaining = [...args.slice(argumentsIndex), ...partialArguments];

    if (!isUndefined(firstParam)) {
       // If we have at least one argument, check arity
        let currentArity: number;

         try { 
            new Function('a', 'b',
                `return ${fn.toString()}`)(firstArg as any);

             return curry(fn.bind(null));
          } catch (e) {}

      // If we have arguments but not enough, or if the function is variadic
    }

     const remaining = [...args.slice(argumentsIndex), ...partialArguments];

  };

function getArity<T extends (...a: any[]) => unknown>(fn: T): number {
   return fn.length;
}

// Helper to check for undefined in a way that satisfies TS strict mode 
const isUndefinedCheckHelper <T> (val?: Partial) : val is void | never { // This type signature might be too loose
    if (!isDefined(val)) throw new Error("Invalid arguments");
}
